"""`harness analyse` — read Claude Code session JSONL, emit HTML/JSON/Markdown timeline."""

from __future__ import annotations

import contextlib
import json
from dataclasses import asdict
from pathlib import Path

from rich.console import Console
from rich.table import Table

from harness.analyse.aggregator import analyse, fmt_duration
from harness.analyse.parser import (
    Session,
    list_project_sessions,
    list_projects,
    parse_session,
)
from harness.analyse.render import render_html
from harness.analyse.synthesis import synthesise

_CLAUDE_PROJECTS_ROOT = Path.home() / ".claude" / "projects"
_console = Console()
_err = Console(stderr=True)


def cmd_list_projects() -> int:
    projects = list_projects(_CLAUDE_PROJECTS_ROOT)
    if not projects:
        _err.print(f"[yellow]no projects under {_CLAUDE_PROJECTS_ROOT}[/yellow]")
        return 1
    tbl = Table(show_header=True, header_style="bold")
    tbl.add_column("Project slug")
    tbl.add_column("Sessions", justify="right")
    tbl.add_column("Newest")
    for p in projects:
        sessions = list_project_sessions(p)
        newest = sessions[0].stat().st_mtime if sessions else 0
        from datetime import datetime as _dt
        newest_str = _dt.fromtimestamp(newest).strftime("%Y-%m-%d %H:%M") if newest else "-"
        tbl.add_row(p.name, str(len(sessions)), newest_str)
    _console.print(tbl)
    return 0


def cmd_list_sessions(project: str) -> int:
    proj_dir = _resolve_project(project)
    if proj_dir is None:
        return 1
    sessions = list_project_sessions(proj_dir)
    if not sessions:
        _err.print(f"[yellow]no sessions under {proj_dir}[/yellow]")
        return 1
    tbl = Table(show_header=True, header_style="bold")
    tbl.add_column("Session id")
    tbl.add_column("Modified")
    tbl.add_column("Size", justify="right")
    from datetime import datetime as _dt
    for s in sessions:
        st = s.stat()
        tbl.add_row(
            s.stem,
            _dt.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M"),
            f"{st.st_size // 1024} KB",
        )
    _console.print(tbl)
    return 0


def cmd_analyse(
    *,
    project: str | None,
    session: str | None,
    latest: bool,
    all_sessions: bool = False,
    out_dir: Path,
    format: str,
    skip_synthesis: bool,
    model: str,
) -> int:
    proj_dir = _resolve_project(project)
    if proj_dir is None:
        return 1

    sessions = list_project_sessions(proj_dir)
    if not sessions:
        _err.print(f"[red]no sessions under {proj_dir}[/red]")
        return 1

    # ---- --all path: stitch every session into one timeline -----------------
    if all_sessions:
        if session or latest:
            _err.print(
                "[red]--all is exclusive with --session and --latest.[/red]"
            )
            return 1
        return _render_all_sessions(
            sessions=sessions,
            out_dir=out_dir,
            format=format,
            skip_synthesis=skip_synthesis,
            model=model,
        )

    target: Path | None = None
    if session:
        for s in sessions:
            if s.stem == session or s.stem.startswith(session):
                target = s
                break
        if target is None:
            _err.print(f"[red]session id {session!r} not found in {proj_dir}[/red]")
            return 1
    else:
        if not latest and len(sessions) > 1:
            _err.print(
                f"[yellow]multiple sessions; pass --session ID, --latest, or --all. "
                f"Most recent: {sessions[0].stem}[/yellow]"
            )
            return 1
        target = sessions[0]

    written = _render_once(
        target=target,
        out_dir=out_dir,
        format=format,
        skip_synthesis=skip_synthesis,
        model=model,
        auto_refresh_seconds=None,
        verbose=True,
    )
    _console.print(f"[green]wrote[/green] {len(written)} file(s):")
    for p in written:
        _console.print(f"  {p}")
    return 0


def _render_all_sessions(
    *,
    sessions: list[Path],
    out_dir: Path,
    format: str,
    skip_synthesis: bool,
    model: str,
) -> int:
    """Parse every session, stitch into one cross-session timeline, render."""
    from dataclasses import replace
    from datetime import datetime

    from harness.analyse.aggregator import PhaseMetrics, SessionAnalysis

    _console.print(f"[dim]parsing {len(sessions)} session(s)…[/dim]")

    parsed: list[Session] = []
    analyses: list[SessionAnalysis] = []
    for sess_path in sessions:
        try:
            sess = parse_session(sess_path)
        except Exception as e:
            _err.print(f"[yellow]skipping {sess_path.stem} (parse failed: {e})[/yellow]")
            continue
        parsed.append(sess)
        analyses.append(analyse(sess))

    if not analyses:
        _err.print("[red]no parseable sessions[/red]")
        return 1

    # Sort by started_at ascending (oldest first) so the timeline reads chronologically.
    indexed = list(zip(parsed, analyses, strict=True))
    indexed.sort(key=lambda pair: pair[0].started_at or datetime.min)

    # Build the merged Session: concat turns, span start/end.
    all_turns = []
    for s, _ in indexed:
        all_turns.extend(s.turns)
    started_at = min(
        (s.started_at for s, _ in indexed if s.started_at), default=None
    )
    ended_at = max(
        (s.ended_at for s, _ in indexed if s.ended_at), default=None
    )
    merged_session = Session(
        session_id="all-" + indexed[0][0].session_id[:8],
        project_slug=indexed[0][0].project_slug,
        title=f"All sessions ({len(indexed)}) — stitched timeline",
        started_at=started_at,
        ended_at=ended_at,
        cwd=indexed[0][0].cwd,
        git_branch=indexed[0][0].git_branch,
        turns=all_turns,
        raw_count=sum(s.raw_count for s, _ in indexed),
    )

    # Build merged phase list: rewrite index sequentially; prefix titles with
    # session id + date so the timeline still distinguishes sessions visually.
    merged_phases = []
    next_index = 0
    for sess, analysis in indexed:
        date_str = (
            sess.started_at.strftime("%Y-%m-%d %H:%M")
            if sess.started_at else "(no-time)"
        )
        sid_short = sess.session_id[:8]
        for phase in analysis.phases:
            new_title = f"[{sid_short} · {date_str}] {phase.title}"
            merged_phases.append(replace(
                phase,
                index=next_index,
                title=new_title,
            ))
            next_index += 1

    # Sum metrics + cost across sessions. PhaseMetrics has mixed field types
    # (Counter / list / int / dict[str, list]), so merge per-type.
    from collections import Counter as _Counter
    sum_metrics = PhaseMetrics()
    for _, analysis in indexed:
        m = analysis.total_metrics
        for fname in sum_metrics.__dataclass_fields__:
            cur = getattr(sum_metrics, fname)
            other = getattr(m, fname)
            if isinstance(cur, _Counter):
                setattr(sum_metrics, fname, cur + other)
            elif isinstance(cur, dict):
                for k, v in other.items():
                    if k in cur:
                        cur[k].extend(v)
                    else:
                        cur[k] = list(v)
            elif isinstance(cur, (list, int)):
                setattr(sum_metrics, fname, cur + other)
            else:
                setattr(sum_metrics, fname, other)
    total_cost = sum(a.total_cost_usd for _, a in indexed)

    merged_analysis = SessionAnalysis(
        session=merged_session,
        phases=merged_phases,
        total_metrics=sum_metrics,
        total_cost_usd=total_cost,
    )

    # Narrative across the merged timeline.
    if skip_synthesis:
        from harness.analyse.synthesis import _empty_narrative
        narrative = _empty_narrative(len(merged_phases))
    else:
        _console.print("[dim]synthesising cross-session narrative via claude CLI…[/dim]")
        narrative = synthesise(merged_analysis, model=model)

    out_dir.mkdir(parents=True, exist_ok=True)
    base = out_dir / f"all-{indexed[0][0].project_slug or 'sessions'}"
    written: list[Path] = []

    if format in ("html", "all"):
        html = render_html(merged_analysis, narrative, auto_refresh_seconds=None)
        html_path = base.with_suffix(".html")
        _atomic_write_text(html_path, html)
        written.append(html_path)
    if format in ("json", "all"):
        json_path = base.with_suffix(".json")
        _atomic_write_text(
            json_path,
            json.dumps(_to_jsonable(merged_session, merged_analysis, narrative), indent=2, default=str),
        )
        written.append(json_path)
    if format in ("md", "all"):
        md_path = base.with_suffix(".md")
        _atomic_write_text(md_path, _render_md(merged_session, merged_analysis, narrative))
        written.append(md_path)

    _console.print(
        f"[green]wrote[/green] {len(written)} file(s) "
        f"covering {len(indexed)} session(s) — "
        f"{len(merged_phases)} phase(s) total:"
    )
    for p in written:
        _console.print(f"  {p}")
    return 0


def _render_once(
    *,
    target: Path,
    out_dir: Path,
    format: str,
    skip_synthesis: bool,
    model: str,
    auto_refresh_seconds: int | None = None,
    verbose: bool = False,
) -> list[Path]:
    """Parse one session JSONL and render the requested output format(s).

    Pure helper shared by `cmd_analyse` and `harness.analyse.watch`. Does NOT
    resolve project / select session — caller passes the resolved target path.

    Returns the list of written file paths.
    """
    if verbose:
        _console.print(f"[dim]parsing[/dim] {target}")
    sess = parse_session(target)
    analysis = analyse(sess)

    if skip_synthesis:
        from harness.analyse.synthesis import _empty_narrative
        narrative = _empty_narrative(len(analysis.phases))
    else:
        if verbose:
            _console.print("[dim]synthesising narrative via claude CLI…[/dim]")
        narrative = synthesise(analysis, model=model)

    out_dir.mkdir(parents=True, exist_ok=True)
    base = out_dir / f"session-{sess.session_id[:8]}"
    written: list[Path] = []

    if format in ("html", "all"):
        html = render_html(analysis, narrative, auto_refresh_seconds=auto_refresh_seconds)
        html_path = base.with_suffix(".html")
        _atomic_write_text(html_path, html)
        written.append(html_path)
    if format in ("json", "all"):
        json_path = base.with_suffix(".json")
        _atomic_write_text(
            json_path,
            json.dumps(_to_jsonable(sess, analysis, narrative), indent=2, default=str),
        )
        written.append(json_path)
    if format in ("md", "all"):
        md_path = base.with_suffix(".md")
        _atomic_write_text(md_path, _render_md(sess, analysis, narrative))
        written.append(md_path)

    return written


def cmd_watch(
    *,
    project: str | None,
    session: str | None,
    latest: bool,
    out_dir: Path,
    format: str,
    skip_synthesis: bool,
    model: str,
    interval_seconds: int,
) -> int:
    """Resolve target session, then run the watch poll-loop."""
    from harness.analyse.watch import watch_loop

    proj_dir = _resolve_project(project)
    if proj_dir is None:
        return 1

    sessions = list_project_sessions(proj_dir)
    if not sessions:
        _err.print(f"[red]no sessions under {proj_dir}[/red]")
        return 1

    target: Path | None = None
    if session:
        for s in sessions:
            if s.stem == session or s.stem.startswith(session):
                target = s
                break
        if target is None:
            _err.print(f"[red]session id {session!r} not found in {proj_dir}[/red]")
            return 1
    else:
        if not latest and len(sessions) > 1:
            _err.print(
                "[yellow]multiple sessions; pass --session ID or --latest[/yellow]"
            )
            return 1
        target = sessions[0]

    _console.print(f"[dim]watching[/dim] {target} every {interval_seconds}s")
    _console.print(f"[dim]output:[/dim] {out_dir}/session-{target.stem[:8]}.html")
    return watch_loop(
        target=target,
        out_dir=out_dir,
        format=format,
        skip_synthesis=skip_synthesis,
        model=model,
        interval_seconds=interval_seconds,
    )


def _atomic_write_text(path: Path, content: str) -> None:
    """Write text atomically (tempfile + os.replace) so browser tabs never
    catch a half-written HTML mid-refresh under --watch mode."""
    import os
    import tempfile
    fd, tmp_name = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fp:
            fp.write(content)
        os.replace(tmp_name, str(path))
    except Exception:
        # cleanup tmp on failure
        with contextlib.suppress(FileNotFoundError):
            os.unlink(tmp_name)
        raise


def _resolve_project(project: str | None) -> Path | None:
    if not project:
        # default to cwd-derived slug
        slug = _slug_for(Path.cwd())
        guess = _CLAUDE_PROJECTS_ROOT / slug
        if not guess.is_dir():
            _err.print(
                f"[red]no project at {guess}; pass --project or run from a project root.[/red]"
            )
            return None
        return guess
    if project.startswith("-Users-"):
        # already a slug
        cand = _CLAUDE_PROJECTS_ROOT / project
    else:
        # accept either a substring or a path
        path = Path(project).expanduser().resolve()
        if path.is_dir() and (path.parent == _CLAUDE_PROJECTS_ROOT):
            return path
        slug = _slug_for(path) if path.exists() else project
        cand = _CLAUDE_PROJECTS_ROOT / slug
        if not cand.is_dir():
            # fallback: substring search
            matches = [p for p in list_projects(_CLAUDE_PROJECTS_ROOT) if project in p.name]
            if len(matches) == 1:
                cand = matches[0]
            elif len(matches) > 1:
                _err.print(f"[red]ambiguous project {project!r}; matches:[/red]")
                for m in matches:
                    _err.print(f"  {m.name}")
                return None
    if not cand.is_dir():
        _err.print(f"[red]no project found for {project!r} (looked at {cand})[/red]")
        return None
    return cand


def _slug_for(path: Path) -> str:
    """Convert an absolute path to the slug Claude Code uses for project dirs.
    `/`, `.`, and space all become `-` (matches the runtime's transform).
    Spaces in paths (e.g. `NEW RESERACH`) are common on macOS and must be
    handled or `harness analyse` can't find the session dir."""
    s = str(path).lstrip("/")
    return "-" + s.replace("/", "-").replace(".", "-").replace(" ", "-")


def _to_jsonable(sess: Session, analysis, narrative) -> dict:
    return {
        "session": {
            "id": sess.session_id,
            "project_slug": sess.project_slug,
            "title": sess.title,
            "started_at": str(sess.started_at) if sess.started_at else None,
            "ended_at": str(sess.ended_at) if sess.ended_at else None,
            "duration_seconds": sess.duration_seconds,
            "git_branch": sess.git_branch,
            "cwd": sess.cwd,
            "raw_count": sess.raw_count,
            "turn_count": len(sess.turns),
        },
        "phases": [
            {
                "index": ph.index,
                "title": ph.title,
                "slash_command": ph.slash_command,
                "start": str(ph.start),
                "end": str(ph.end),
                "duration_seconds": ph.duration_seconds,
                "turn_count": len(ph.turns),
                "interventions": [{"timestamp": str(h.timestamp), "text": h.text}
                                  for h in ph.interventions],
                "metrics": {
                    "tools": dict(ph.metrics.tool_counts),
                    "subagents": dict(ph.metrics.subagent_calls),
                    "mcp": dict(ph.metrics.mcp_calls),
                    "files_written": ph.metrics.files_written,
                    "files_edited": ph.metrics.files_edited,
                    "bash_commands": ph.metrics.bash_commands,
                    "input_tokens": ph.metrics.input_tokens,
                    "output_tokens": ph.metrics.output_tokens,
                    "cache_create_tokens": ph.metrics.cache_create_tokens,
                    "cache_read_tokens": ph.metrics.cache_read_tokens,
                },
            }
            for ph in analysis.phases
        ],
        "totals": {
            "tools": dict(analysis.total_metrics.tool_counts),
            "subagents": dict(analysis.total_metrics.subagent_calls),
            "mcp": dict(analysis.total_metrics.mcp_calls),
            "input_tokens": analysis.total_metrics.input_tokens,
            "output_tokens": analysis.total_metrics.output_tokens,
            "cache_create_tokens": analysis.total_metrics.cache_create_tokens,
            "cache_read_tokens": analysis.total_metrics.cache_read_tokens,
            "cost_usd": analysis.total_cost_usd,
        },
        "narrative": {
            "one_line_summary": narrative.one_line_summary,
            "end_cap_title": narrative.end_cap_title,
            "end_cap_body": narrative.end_cap_body,
            "pattern_worth_keeping": narrative.pattern_worth_keeping,
            "phases": [asdict(p) for p in narrative.phases],
        },
    }


def _render_md(sess: Session, analysis, narrative) -> str:
    lines: list[str] = []
    title = sess.title or f"Session {sess.session_id[:8]}"
    lines.append(f"# {title}")
    lines.append("")
    lines.append(f"**Session:** `{sess.session_id}`  ")
    lines.append(f"**Duration:** {fmt_duration(sess.duration_seconds)}  ")
    if sess.git_branch:
        lines.append(f"**Branch:** `{sess.git_branch}`  ")
    if narrative.one_line_summary:
        lines.append("")
        lines.append(narrative.one_line_summary)
    lines.append("")

    for ph, narr in zip(analysis.phases, narrative.phases, strict=False):
        lines.append(f"## Phase {ph.index} — {ph.title}")
        lines.append(f"_{ph.start.strftime('%H:%M:%S')} → {ph.end.strftime('%H:%M:%S')} · {fmt_duration(ph.duration_seconds)}_")
        if narr.specific_run:
            lines.append("")
            lines.append(narr.specific_run)
        if ph.metrics.tool_counts:
            lines.append("")
            lines.append("**Tools:** " + ", ".join(f"`{n}` ×{c}" for n, c in ph.metrics.tool_counts.most_common(10)))
        if ph.metrics.files_written:
            lines.append("")
            lines.append("**Written:** " + ", ".join(f"`{f}`" for f in ph.metrics.files_written[:8]))
        if ph.metrics.files_edited:
            lines.append("**Edited:** " + ", ".join(f"`{f}`" for f in ph.metrics.files_edited[:8]))
        if ph.interventions:
            lines.append("")
            lines.append(f"**Human-in-loop ({len(ph.interventions)} intervention(s)):**")
            for h in ph.interventions[:3]:
                first = h.text.splitlines()[0][:200]
                lines.append(f"> {first}")
        lines.append("")

    if narrative.end_cap_body:
        lines.append("## End")
        lines.append(narrative.end_cap_body)
    if narrative.pattern_worth_keeping:
        lines.append("")
        lines.append(f"**Pattern worth keeping:** {narrative.pattern_worth_keeping}")
    return "\n".join(lines)
